<script setup>
import { reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { useRouter } from 'vue-router'
import { register } from '../../api/auth'
const router=useRouter();const formRef=ref();const busy=ref(false);const form=reactive({username:'',password:'',confirmPassword:'',nickname:'',phone:'',email:''});const confirmRule=(rule,value,done)=>value!==form.password?done(new Error('两次输入的密码不一致')):done();const rules={username:[{required:true,message:'请输入用户名',trigger:'blur'},{min:4,max:20,message:'用户名长度为4-20位',trigger:'blur'},{pattern:/^[a-zA-Z0-9_]+$/,message:'仅支持字母、数字、下划线',trigger:'blur'}],password:[{required:true,message:'请输入密码'},{min:6,max:20,message:'密码长度为6-20位',trigger:'blur'}],confirmPassword:[{required:true,message:'请确认密码'},{validator:confirmRule,trigger:'blur'}],phone:[{pattern:/^$|^1[3-9]\d{9}$/,message:'手机号格式不正确',trigger:'blur'}],email:[{type:'email',message:'邮箱格式不正确',trigger:'blur'}]}
async function submit(){await formRef.value.validate();busy.value=true;try{await register({...form,nickname:form.nickname||null,phone:form.phone||null,email:form.email||null});ElMessage.success('注册成功，请登录');router.replace({path:'/login',query:{username:form.username}})}finally{busy.value=false}}
</script>
<template><main class="auth-page"><section class="auth-art"><span class="eyebrow">JOIN THE COLLECTION</span><h1>创建你的<br/>唱片架。</h1><p>注册账户，收藏你的下一张心头好。</p></section><section class="auth-card"><RouterLink to="/" class="brand">◉ 潮汐唱片</RouterLink><h2 style="margin-top:26px">创建账号</h2><el-form ref="formRef" :model="form" :rules="rules" label-position="top" @submit.prevent="submit"><el-form-item label="用户名" prop="username"><el-input v-model="form.username" autocomplete="username"/></el-form-item><div class="form-grid"><el-form-item label="密码" prop="password"><el-input v-model="form.password" type="password" show-password autocomplete="new-password"/></el-form-item><el-form-item label="确认密码" prop="confirmPassword"><el-input v-model="form.confirmPassword" type="password" show-password autocomplete="new-password"/></el-form-item></div><el-form-item label="昵称"><el-input v-model="form.nickname" maxlength="50"/></el-form-item><div class="form-grid"><el-form-item label="手机号" prop="phone"><el-input v-model="form.phone"/></el-form-item><el-form-item label="邮箱" prop="email"><el-input v-model="form.email"/></el-form-item></div><el-button type="primary" style="width:100%" :loading="busy" @click="submit">注册</el-button></el-form><p class="auth-foot">已有账号？<RouterLink to="/login" class="login-link">前往登录</RouterLink></p></section></main></template>
